#!/bin/bash
set -e
cd /home/user/MarketSummary
rm -rf /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry && mkdir -p /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry
uv run python -m cdp --book /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/book --reports /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/reports weekly prepare --date 2026-10-05 --mind claude-code --offline > /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/prepare.json
cp ${1:-/tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/research/research_pack_input.json} /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/book/2026-10-05/inputs/research_pack.json
cp ${2:-/tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/research/pm_decision_input.json} /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/book/2026-10-05/inputs/pm_decision.json
uv run python -m cdp --book /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/book --reports /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/reports validate --week 2026-10-05 --mind claude-code
uv run python -m cdp --book /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/book --reports /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/reports weekly decide --week 2026-10-05 --mind claude-code > /tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/decide.json
python3 -c "import json;d=json.load(open('/tmp/claude-0/-home-user-MarketSummary/51d8515e-fc24-58f0-ab60-fbec2a191c25/scratchpad/dry/decide.json'));[print(k,d[k]) for k in ('caminho','vol_ex_ante','gross','net','beta','n_long','n_short','falhas_soft')]"
